abstract class Vehicle{String name;boolean available=true;Vehicle(String n){name=n;}abstract double calculateCharge(int days);}class Sedan extends Vehicle{Sedan(String n){super(n);}double calculateCharge(int d){return d*50;}}class SUV extends Vehicle{SUV(String n){super(n);}double calculateCharge(int d){return d*80;}}class Customer{String name;Customer(String n){name=n;}}class Rental{Vehicle vehicle;Customer customer;Rental(Vehicle v,Customer c){vehicle=v;customer=c;}void returnVehicle(){vehicle.available=true;System.out.println(vehicle.name+" returned");}}
public class VehicleRentalSystem{public static void main(String[] args){Vehicle sedan=new Sedan("Sedan A"),suv=new SUV("SUV B");Customer c1=new Customer("Customer 1"),c3=new Customer("Customer 3");if(sedan.available){sedan.available=false;new Rental(sedan,c1);System.out.println("Sedan A rented successfully");System.out.println("Charge: $"+sedan.calculateCharge(3));}if(!sedan.available)System.out.println("Sedan A unavailable");Rental r=new Rental(sedan,c1);r.returnVehicle();if(suv.available){suv.available=false;new Rental(suv,c3);System.out.println("SUV B rented successfully");System.out.println("Charge: $"+suv.calculateCharge(5));}}}